          <HeroFullBleed {...{"title":"Стоматологическая клиника в Казани","action":{"label":"Записаться","href":"/booking#form"},"secondary":{"label":"Открыть каталог","href":"/services"}}} image={photo.one("top", {"src":"/_wizard/photos/6a929ab5-bea4-5d37-b68e-27e3f57dc4fc/1600","alt":"Первый экран — фото по теме «медицинская клиника»"})} />
        </div>
        <div id="catalog">
          <CatalogFeatured {...{"entity":"service","title":"Услуги","empty":"В каталоге пока нет позиций","action":{"label":"Весь каталог","href":"/services"},"pageSize":6,"preview":true,"itemAction":{"label":"Записаться","path":"/booking"}}} />
        </div>
        <div id="contacts">
          <ContactsCards {...{"title":"Контакты","address":{"text":"Казань, ул. Баумана, 12"}}} />
        </div>
      </main>
